#!/usr/bin/env node
/**
 * AURA — group chats
 *
 *   - Messages > New group: give it a name and pick up to 9 friends (10 people in all).
 *   - Groups sit in your Messages list with your other chats. Text, pictures, GIFs, videos,
 *     likes, deleting your own messages and reporting all work as in other chats.
 *   - Each message shows who sent it. Lines like "Alex added Cam" show what changed.
 *   - Click the group's name: everyone in it, rename it, add or remove people (whoever made
 *     the group), Leave group. If the person who made it leaves, the longest member takes over.
 *   - Call: pick one or two people from the group (calls have up to 3 people).
 *   - Someone you've blocked can't add you to a group, and their messages in a group are hidden.
 *   - Chats between two people aren't changed.
 *
 * How to use:
 *   1. Put this file in your AURA project folder (the one with package.json).
 *   2. Fully quit AURA.
 *   3. Run:   node aura-messages-groups-setup.cjs
 *   4. In Supabase, run the new file supabase/aura-messages-groups.sql once (SQL Editor > New
 *      query > paste > Run). Until then, making a group says which file to run.
 *
 * What it does:
 *   - edits    src/components/messages.jsx           New group, the group's card, group calls
 *   - edits    electron/social.js and preload.js      making and changing groups
 *   - creates  supabase/aura-messages-groups.sql      the database rules (run it in Supabase)
 *   - creates  tests for all of it                    (only if AURA's checks are installed)
 *
 * Every file it changes is copied to <name>.before-group-chats.bak first.
 * To put everything back:                 node aura-messages-groups-setup.cjs --undo
 * To preview without changing anything:   node aura-messages-groups-setup.cjs --dry-run
 */
"use strict";
const fs = require("fs");
const os = require("os");
const path = require("path");
const { spawnSync } = require("child_process");
const crypto = require("crypto");

